{"packet_id":"D056-02","doc_id":"D056","jurisdiction":"MA","category":"application_screening_fees","lifecycle":"enacted","title":"CORI fee waiver for veterans organizations","requirement":"No fee shall be assessed for a CORI or self-audit when a veterans organization requests information about employees, volunteers, or veterans for which the organization provides housing.","key_value":"no fee","coverage_conditions":"Requests by any veterans organization for a CORI or self-audit relative to employees, volunteers, or veterans for which the organization provides housing.","applicability":{"conditions":[],"per_tenancy":"Only where a veterans organization requests the CORI or self-audit for employees, volunteers, or veterans it houses.","coverage_quotes":[]},"exemptions":null,"penalty":null,"effective_date":null,"valid_through":null,"citation":"803 CMR 5.18","quoted_span":"no fee shall be assessed for a CORI or self-audit where any veterans organization is requesting information relative to employees, volunteers, or veterans for which such organization provides housing.","interaction":null,"relations":[],"confidence":0.85,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D056-02","doc_id":"D056","jurisdiction":"MA","category":"screening_restrictions","lifecycle":"enacted","title":"CORI access for purposes other than evaluating a housing applicant","requirement":"Nothing in 803 CMR 5.00 limits a landlord, property management company, real estate agent, or public housing authority from accessing CORI under other sections of 803 CMR 2.00, including as an employer or member of the general public.","key_value":null,"coverage_conditions":"Landlords, property management companies, real estate agents, and public housing authorities that access CORI.","applicability":{"conditions":[],"per_tenancy":null,"coverage_quotes":[]},"exemptions":null,"penalty":null,"effective_date":null,"valid_through":null,"citation":"803 CMR 5.17","quoted_span":"Nothing in 803 CMR 5.00 shall limit the ability of a landlord, property management company, real estate agent, or public housing authority to access CORI pursuant to any other section of 803 CMR 2.00: Criminal Offender Record Information (CORI)","interaction":null,"relations":[],"confidence":0.6,"conflict_flag":false,"conflict_note":null}
